# section 4
t = [1 + 3*k for k in range(7)]
assert t == [1, 4, 7, 10, 13, 16, 19] == [3*n - 2 for n in range(1, 8)] and len(t) - 1 == 6
assert [v for v in t if v % 2] == [1, 7, 13, 19] and [v for v in t if v % 2 == 0] == [4, 10, 16]
assert all((t[i] + t[i+1]) % 2 == 1 for i in range(6))
big = [1 + 3*k for k in range(100)]
assert big.index(49) + 1 == 17 and 50 not in big and (50 - 1) % 3 != 0
# parity theorem, both cases
for a1 in range(0, 12):
    for d in range(0, 12):
        s = [a1 + (n - 1)*d for n in range(1, 40)]
        if d % 2 == 0: assert all(v % 2 == a1 % 2 for v in s)
        else: assert all(s[i] % 2 != s[i+1] % 2 for i in range(38))
for a in range(0, 10):
    for d in range(1, 8):
        terms = {a + (n - 1)*d for n in range(1, 400)}
        for N in range(0, 300):
            assert (N in terms) == (N >= a and (N - a) % d == 0)
            if N in terms: assert a + ((N - a)//d)*d == N
assert 50 - 2 == 48 == 12*4 and 2 + 12*4 == 50 and (48//4) + 1 == 13 and (51 - 2) % 4 != 0 and 49 == 51 - 2
assert all((5*n) % 2 == n % 2 for n in range(1, 100)) and [5, 10, 15, 20] == [5*n for n in range(1, 5)]
assert all((4*n) % 2 == 0 and 4*n == 2*(2*n) for n in range(1, 100))
assert 100 - 1 == 99 == 33*3 and 99//3 + 1 == 34 and 199 == 66*3 + 1 and 200 - 1 == 199
assert 3 + 99*7 == 696 and 696 % 2 == 0 and [3 + 7*k for k in range(4)] == [3, 10, 17, 24]
# mod 3
for a in range(0, 30):
    for d in range(1, 30):
        if d % 3 == 0: continue
        for n in range(0, 10):
            trio = [a + (n + i)*d for i in range(3)]
            assert sum(1 for v in trio if v % 3 == 0) == 1 and sorted(v % 3 for v in trio) == [0, 1, 2]
assert [[(s + i) % 3 for i in range(3)] for s in range(3)] == [[0, 1, 2], [1, 2, 0], [2, 0, 1]]
assert [[(s + 2*i) % 3 for i in range(3)] for s in range(3)] == [[0, 2, 1], [1, 0, 2], [2, 1, 0]] and all((s + 4) % 3 == (s + 1) % 3 for s in range(3))
assert (2 + 2) - 3 == 1 and [v % 3 for v in (2, 6, 10)] == [2, 0, 1] and 6 - 2 == 4 == 3*1 + 1
assert [v % 3 for v in (1, 3, 5)] == [1, 0, 2] and 3 - 1 == 2 == 3*0 + 2
assert all((1 + 3*k) % 3 == 1 for k in range(100)) and [1 + 3*k for k in range(4)] == [1, 4, 7, 10]
